() => {
  // find elements containing the refusal bar text
  const all = Array.from(document.querySelectorAll('div,section,article'));
  const bar = all.find(el => el.textContent.includes('问数仅支持当前数据源相关的数据分析') && el.textContent.length < 500);
  // find the closest message bubble container
  let bubble = bar;
  let results = [];
  if (bar) {
    let node = bar;
    for (let i=0;i<4;i++){ if(node.parentElement){ node = node.parentElement; } }
    results.push(node.innerText);
  }
  return { bubbleText: results[0] || null };
}

() => {
  const all = Array.from(document.querySelectorAll('div,section,article,p,span'));
  const bar = all.find(el => el.textContent.trim() === '问数仅支持当前数据源相关的数据分析；该问题与数据无关或数据源中缺少支撑数据，未生成任何结果。');
  if (bar) bar.scrollIntoView({block:'center'});
  return bar ? 'scrolled' : 'not found';
}
